INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15938, 'Tata Sons AGM Faces Potential Postponement Due to Quorum Issue', 'टाटा संस की एजीएम कोरम की समस्या के कारण स्थगित होने की कगार पर', 'The Annual General Meeting (AGM) of Tata Sons was scheduled to take place today, August 15. However, the meeting faces a potential postponement because the quorum, the minimum number of members required to conduct business, may not be met. This issue arose following N. Chandrasekaran''s resignation as Chairman of Tata Sons on August 12. The AGM''s proceedings are contingent on fulfilling the quorum requirement.', 'टाटा संस की वार्षिक आम बैठक (एजीएम) आज, 15 अगस्त को निर्धारित थी। हालांकि, बैठक को स्थगित किए जाने का खतरा है क्योंकि कोरम, यानी व्यवसाय संचालित करने के लिए आवश्यक सदस्यों की न्यूनतम संख्या, पूरी नहीं हो सकती है। यह समस्या 12 अगस्त को टाटा संस के चेयरमैन पद से एन. चंद्रशेखरन के इस्तीफे के बाद उत्पन्न हुई। एजीएम की कार्यवाही कोरम की आवश्यकता को पूरा करने पर निर्भर करती है।', '["Tata Sons'' Annual General Meeting (AGM) was scheduled for August 15.", "The meeting is at risk of being postponed.", "The potential postponement is due to an anticipated failure to meet the required quorum.", "N. Chandrasekaran resigned as Chairman of Tata Sons on August 12."]'::jsonb, '["टाटा संस की वार्षिक आम बैठक (एजीएम) 15 अगस्त को निर्धारित थी।", "बैठक के स्थगित होने का खतरा है।", "संभावित स्थगन आवश्यक कोरम को पूरा करने में अपेक्षित विफलता के कारण है।", "एन. चंद्रशेखरन ने 12 अगस्त को टाटा संस के चेयरमैन पद से इस्तीफा दे दिया था।"]'::jsonb, 'Politics', 'India', 0, 1, 1, 0, 0, 2, 'center', 50, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Jansatta"], "owners": ["Indian Express Group"]}, "right": {"count": 1, "sources": ["Aaj Tak"], "owners": ["India Today Group"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "Jansatta", "owner": "Indian Express Group", "lean": "center", "language": "hi", "url": "https://news.google.?oc=5", "headline": "टाटा संस की AGM में आज क्या होगा? कोरम पूरा नहीं होने पर टल सकती है बैठक"}, {"source": "Aaj Tak", "owner": "India Today Group", "lean": "right", "language": "hi", "url": "https://www.aajtak.in/business/news/story/tata-sons-agm-today-meeting-may-be-postpone-by-new-rule-tutd-dskc-2624788-2026-08-18", "headline": "टाटा ग्रुप की आज बड़ी बैठक, लेकिन अचानक आई ये अड़चन"}]'::jsonb, '{"title": "Tata Sons AGM Faces Potential Postponement Due to Quorum Issue", "summary": "The Annual General Meeting (AGM) of Tata Sons was scheduled to take place today, August 15. However, the meeting faces a potential postponement because the quorum, the minimum number of members required to conduct business, may not be met. This issue arose following N. Chandrasekaran''s resignation as Chairman of Tata Sons on August 12. The AGM''s proceedings are contingent on fulfilling the quorum requirement.", "summary_points": ["Tata Sons'' Annual General Meeting (AGM) was scheduled for August 15.", "The meeting is at risk of being postponed.", "The potential postponement is due to an anticipated failure to meet the required quorum.", "N. Chandrasekaran resigned as Chairman of Tata Sons on August 12."], "title_hi": "टाटा संस की एजीएम कोरम की समस्या के कारण स्थगित होने की कगार पर", "summary_hi": "टाटा संस की वार्षिक आम बैठक (एजीएम) आज, 15 अगस्त को निर्धारित थी। हालांकि, बैठक को स्थगित किए जाने का खतरा है क्योंकि कोरम, यानी व्यवसाय संचालित करने के लिए आवश्यक सदस्यों की न्यूनतम संख्या, पूरी नहीं हो सकती है। यह समस्या 12 अगस्त को टाटा संस के चेयरमैन पद से एन. चंद्रशेखरन के इस्तीफे के बाद उत्पन्न हुई। एजीएम की कार्यवाही कोरम की आवश्यकता को पूरा करने पर निर्भर करती है।", "summary_points_hi": ["टाटा संस की वार्षिक आम बैठक (एजीएम) 15 अगस्त को निर्धारित थी।", "बैठक के स्थगित होने का खतरा है।", "संभावित स्थगन आवश्यक कोरम को पूरा करने में अपेक्षित विफलता के कारण है।", "एन. चंद्रशेखरन ने 12 अगस्त को टाटा संस के चेयरमैन पद से इस्तीफा दे दिया था।"], "framing": {}, "framing_hi": {}, "topic": "Politics", "region": "India", "published_at": null, "image_url": "", "sources": [{"source": "Jansatta", "owner": "Indian Express Group", "lean": "center", "language": "hi", "url": "https://news.google.?oc=5", "headline": "टाटा संस की AGM में आज क्या होगा? कोरम पूरा नहीं होने पर टल सकती है बैठक"}, {"source": "Aaj Tak", "owner": "India Today Group", "lean": "right", "language": "hi", "url": "https://www.aajtak.in/business/news/story/tata-sons-agm-today-meeting-may-be-postpone-by-new-rule-tutd-dskc-2624788-2026-08-18", "headline": "टाटा ग्रुप की आज बड़ी बैठक, लेकिन अचानक आई ये अड़चन"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Jansatta"], "owners": ["Indian Express Group"]}, "right": {"count": 1, "sources": ["Aaj Tak"], "owners": ["India Today Group"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, NULL, FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.664016'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15937, 'UPSC Exam Controversy: CAT Issues Notice to Commission Over Alleged Flawed Questions', 'यूपीएससी परीक्षा विवाद: कथित त्रुटिपूर्ण प्रश्नों पर आयोग को कैट ने भेजा नोटिस', 'The Union Public Service Commission (UPSC) is facing controversy regarding the Civil Services Preliminary Examination 2026. Candidates have filed a petition challenging eight allegedly "incorrect and defective" questions in the GS Paper-1. The Central Administrative Tribunal (CAT) has issued a notice to the UPSC, seeking its response to the petition. This development raises questions about the preliminary exam shortly before the Mains examination.', 'संघ लोक सेवा आयोग (UPSC) 2026 की सिविल सेवा प्रारंभिक परीक्षा को लेकर विवादों में है। अभ्यर्थियों ने जीएस पेपर-1 के आठ कथित "गलत और त्रुटिपूर्ण" सवालों को चुनौती देते हुए एक याचिका दायर की है। सेंट्रल एडमिनिस्ट्रेटिव ट्रिब्यूनल (CAT) ने याचिका पर सुनवाई करते हुए यूपीएससी को नोटिस जारी कर जवाब मांगा है। यह घटनाक्रम मुख्य परीक्षा से ठीक पहले प्रारंभिक परीक्षा पर सवाल खड़े करता है।', '["The UPSC Civil Services Preliminary Examination 2026 is under scrutiny.", "Candidates have filed a petition challenging eight questions from GS Paper-1.", "The Central Administrative Tribunal (CAT) has issued a notice to the UPSC.", "The CAT has requested a response from the UPSC regarding the petition.", "The controversy arises shortly before the Mains examination."]'::jsonb, '["यूपीएससी सिविल सेवा प्रारंभिक परीक्षा 2026 जांच के दायरे में है।", "अभ्यर्थियों ने जीएस पेपर-1 के आठ सवालों को चुनौती देते हुए याचिका दायर की है।", "सेंट्रल एडमिनिस्ट्रेटिव ट्रिब्यूनल (CAT) ने यूपीएससी को नोटिस जारी किया है।", "कैट ने याचिका के संबंध में यूपीएससी से जवाब मांगा है।", "यह विवाद मुख्य परीक्षा से ठीक पहले सामने आया है।"]'::jsonb, 'Crime & Law', 'India', 0, 1, 1, 0, 0, 2, 'center', 50, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Navbharat Times"], "owners": ["Times Group"]}, "right": {"count": 1, "sources": ["Aaj Tak"], "owners": ["India Today Group"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "Navbharat Times", "owner": "Times Group", "lean": "center", "language": "hi", "url": "https://navbharattimes.indiatimes.com/education/exam-results/before-upsc-cse-mains-2026-questions-raised-on-8-prelims-questions-cat-issues-notice-to-seeking-commission-response/articleshow/133315156.cms", "headline": "UPSC : बदल सकता है 16 नंबर का गणित , CAT ने आयोग को भेजा नोटिस , मेन्स से ठीक पहले प्रीलिम्स पर उठे सवाल"}, {"source": "Aaj Tak", "owner": "India Today Group", "lean": "right", "language": "hi", "url": "https://www.aajtak.in/education/news/story/upsc-civil-services-prelims-2026-question-dispute-cat-notice-edmm-dskc-2624816-2026-08-18", "headline": "UPSC प्रील‍िम्स के 8 ''डिफेक्ट‍िव'' सवालों पर घिरा आयोग!"}]'::jsonb, '{"title": "UPSC Exam Controversy: CAT Issues Notice to Commission Over Alleged Flawed Questions", "summary": "The Union Public Service Commission (UPSC) is facing controversy regarding the Civil Services Preliminary Examination 2026. Candidates have filed a petition challenging eight allegedly \"incorrect and defective\" questions in the GS Paper-1. The Central Administrative Tribunal (CAT) has issued a notice to the UPSC, seeking its response to the petition. This development raises questions about the preliminary exam shortly before the Mains examination.", "summary_points": ["The UPSC Civil Services Preliminary Examination 2026 is under scrutiny.", "Candidates have filed a petition challenging eight questions from GS Paper-1.", "The Central Administrative Tribunal (CAT) has issued a notice to the UPSC.", "The CAT has requested a response from the UPSC regarding the petition.", "The controversy arises shortly before the Mains examination."], "title_hi": "यूपीएससी परीक्षा विवाद: कथित त्रुटिपूर्ण प्रश्नों पर आयोग को कैट ने भेजा नोटिस", "summary_hi": "संघ लोक सेवा आयोग (UPSC) 2026 की सिविल सेवा प्रारंभिक परीक्षा को लेकर विवादों में है। अभ्यर्थियों ने जीएस पेपर-1 के आठ कथित \"गलत और त्रुटिपूर्ण\" सवालों को चुनौती देते हुए एक याचिका दायर की है। सेंट्रल एडमिनिस्ट्रेटिव ट्रिब्यूनल (CAT) ने याचिका पर सुनवाई करते हुए यूपीएससी को नोटिस जारी कर जवाब मांगा है। यह घटनाक्रम मुख्य परीक्षा से ठीक पहले प्रारंभिक परीक्षा पर सवाल खड़े करता है।", "summary_points_hi": ["यूपीएससी सिविल सेवा प्रारंभिक परीक्षा 2026 जांच के दायरे में है।", "अभ्यर्थियों ने जीएस पेपर-1 के आठ सवालों को चुनौती देते हुए याचिका दायर की है।", "सेंट्रल एडमिनिस्ट्रेटिव ट्रिब्यूनल (CAT) ने यूपीएससी को नोटिस जारी किया है।", "कैट ने याचिका के संबंध में यूपीएससी से जवाब मांगा है।", "यह विवाद मुख्य परीक्षा से ठीक पहले सामने आया है।"], "framing": {}, "framing_hi": {}, "topic": "Crime & Law", "region": "India", "published_at": null, "image_url": "https://static.langimg.com/nbt/thumb/123846288/navbharat-times.jpg?imgsize=123846288&resizemode=75", "sources": [{"source": "Navbharat Times", "owner": "Times Group", "lean": "center", "language": "hi", "url": "https://navbharattimes.indiatimes.com/education/exam-results/before-upsc-cse-mains-2026-questions-raised-on-8-prelims-questions-cat-issues-notice-to-seeking-commission-response/articleshow/133315156.cms", "headline": "UPSC : बदल सकता है 16 नंबर का गणित , CAT ने आयोग को भेजा नोटिस , मेन्स से ठीक पहले प्रीलिम्स पर उठे सवाल"}, {"source": "Aaj Tak", "owner": "India Today Group", "lean": "right", "language": "hi", "url": "https://www.aajtak.in/education/news/story/upsc-civil-services-prelims-2026-question-dispute-cat-notice-edmm-dskc-2624816-2026-08-18", "headline": "UPSC प्रील‍िम्स के 8 ''डिफेक्ट‍िव'' सवालों पर घिरा आयोग!"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Navbharat Times"], "owners": ["Times Group"]}, "right": {"count": 1, "sources": ["Aaj Tak"], "owners": ["India Today Group"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://static.langimg.com/nbt/thumb/123846288/navbharat-times.jpg?imgsize=123846288&resizemode=75', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.639539'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15936, 'Double Murders Reported in Surguja and Bengaluru', 'सरगुजा और बेंगलुरु में दोहरे हत्याकांड की खबरें', 'Two separate double murder incidents have been reported in India. In Surguja, a son allegedly murdered his parents using an axe and fled the scene. In Bengaluru, a woman is suspected of murdering her husband and child, with reports suggesting a lover''s involvement. Details regarding the motive and circumstances of both incidents are still emerging.', 'भारत में दो अलग-अलग दोहरे हत्याकांड की घटनाओं की सूचना मिली है। सरगुजा में, एक बेटे ने कथित तौर पर कुल्हाड़ी से अपने माता-पिता की हत्या कर दी और घटनास्थल से फरार हो गया। बेंगलुरु में, एक महिला पर अपने पति और बच्चे की हत्या का संदेह है, जिसमें कथित तौर पर एक प्रेमी की संलिप्तता की खबरें हैं। दोनों घटनाओं के मकसद और परिस्थितियों का विवरण अभी सामने आ रहा है।', '["A double murder occurred in Surguja where a son allegedly killed his parents.", "The accused in the Surguja case reportedly used an axe and is currently absconding.", "A separate double murder case was reported in Bengaluru.", "In Bengaluru, a husband and child were allegedly murdered by the wife, with reports mentioning a lover''s involvement."]'::jsonb, '["सरगुजा में एक दोहरे हत्याकांड में बेटे पर अपने माता-पिता की हत्या का आरोप है।", "सरगुजा मामले में आरोपी ने कथित तौर पर कुल्हाड़ी का इस्तेमाल किया और फरार है।", "बेंगलुरु में एक अलग दोहरे हत्याकांड की सूचना मिली है।", "बेंगलुरु में, पत्नी पर पति और बच्चे की हत्या का आरोप है, जिसमें कथित तौर पर एक प्रेमी की संलिप्तता का उल्लेख है।"]'::jsonb, 'Crime & Law', 'India', 0, 1, 1, 0, 0, 2, 'center', 50, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Haribhoomi"], "owners": ["Haribhoomi"]}, "right": {"count": 1, "sources": ["Zee News (Hindi)"], "owners": ["Zee News (Hindi)"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "Haribhoomi", "owner": "Haribhoomi", "lean": "center", "language": "hi", "url": "https://news.google.?oc=5", "headline": "सरगुजा में डबल मर्डर से सनसनी : कलयुगी बेटे ने माता-पिता को उतारा मौत के घाट, कुल्हाड़ी से हत्या कर आरोपी फरार"}, {"source": "Zee News (Hindi)", "owner": "Zee News (Hindi)", "lean": "right", "language": "hi", "url": "https://news.google.?oc=5", "headline": "प्रेमी संग पति की हत्या, फिर बच्चे को भी मार डाला! बेंगलुरु के डबल मर्डर ने चौंकाया"}]'::jsonb, '{"title": "Double Murders Reported in Surguja and Bengaluru", "summary": "Two separate double murder incidents have been reported in India. In Surguja, a son allegedly murdered his parents using an axe and fled the scene. In Bengaluru, a woman is suspected of murdering her husband and child, with reports suggesting a lover''s involvement. Details regarding the motive and circumstances of both incidents are still emerging.", "summary_points": ["A double murder occurred in Surguja where a son allegedly killed his parents.", "The accused in the Surguja case reportedly used an axe and is currently absconding.", "A separate double murder case was reported in Bengaluru.", "In Bengaluru, a husband and child were allegedly murdered by the wife, with reports mentioning a lover''s involvement."], "title_hi": "सरगुजा और बेंगलुरु में दोहरे हत्याकांड की खबरें", "summary_hi": "भारत में दो अलग-अलग दोहरे हत्याकांड की घटनाओं की सूचना मिली है। सरगुजा में, एक बेटे ने कथित तौर पर कुल्हाड़ी से अपने माता-पिता की हत्या कर दी और घटनास्थल से फरार हो गया। बेंगलुरु में, एक महिला पर अपने पति और बच्चे की हत्या का संदेह है, जिसमें कथित तौर पर एक प्रेमी की संलिप्तता की खबरें हैं। दोनों घटनाओं के मकसद और परिस्थितियों का विवरण अभी सामने आ रहा है।", "summary_points_hi": ["सरगुजा में एक दोहरे हत्याकांड में बेटे पर अपने माता-पिता की हत्या का आरोप है।", "सरगुजा मामले में आरोपी ने कथित तौर पर कुल्हाड़ी का इस्तेमाल किया और फरार है।", "बेंगलुरु में एक अलग दोहरे हत्याकांड की सूचना मिली है।", "बेंगलुरु में, पत्नी पर पति और बच्चे की हत्या का आरोप है, जिसमें कथित तौर पर एक प्रेमी की संलिप्तता का उल्लेख है।"], "framing": {}, "framing_hi": {}, "topic": "Crime & Law", "region": "India", "published_at": null, "image_url": "", "sources": [{"source": "Haribhoomi", "owner": "Haribhoomi", "lean": "center", "language": "hi", "url": "https://news.google.?oc=5", "headline": "सरगुजा में डबल मर्डर से सनसनी : कलयुगी बेटे ने माता-पिता को उतारा मौत के घाट, कुल्हाड़ी से हत्या कर आरोपी फरार"}, {"source": "Zee News (Hindi)", "owner": "Zee News (Hindi)", "lean": "right", "language": "hi", "url": "https://news.google.?oc=5", "headline": "प्रेमी संग पति की हत्या, फिर बच्चे को भी मार डाला! बेंगलुरु के डबल मर्डर ने चौंकाया"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Haribhoomi"], "owners": ["Haribhoomi"]}, "right": {"count": 1, "sources": ["Zee News (Hindi)"], "owners": ["Zee News (Hindi)"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, NULL, FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.614365'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total