INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15935, 'Actor Yoo Ah-in to Return to Acting After Drug Scandal', 'अभिनेता यू आह-इन ड्रग्स स्कैंडल के बाद अभिनय में वापसी करेंगे', 'South Korean actor Yoo Ah-in is reportedly set to make a comeback to acting. He will star in a new film directed by the helmer of ''Exhuma''. This marks his return after a drug scandal. The film is described as a ''Vampire film''.', 'दक्षिण कोरियाई अभिनेता यू आह-इन के अभिनय में वापसी करने की खबर है। वह ''एक्सुमा'' के निर्देशक की अगली फिल्म में नजर आएंगे। यह ड्रग्स स्कैंडल के बाद उनकी वापसी का प्रतीक है। फिल्म को ''वैम्पायर फिल्म'' के रूप में वर्णित किया गया है।', '["Actor Yoo Ah-in is slated for an acting comeback.", "He will feature in a new film.", "The film will be directed by the director of ''Exhuma''.", "The project is described as a ''Vampire film''.", "This comeback follows a drug scandal involving the actor."]'::jsonb, '["अभिनेता यू आह-इन अभिनय में वापसी के लिए तैयार हैं।", "वह एक नई फिल्म में नजर आएंगे।", "फिल्म का निर्देशन ''एक्सुमा'' के निर्देशक करेंगे।", "इस परियोजना को ''वैम्पायर फिल्म'' के रूप में वर्णित किया गया है।", "यह वापसी अभिनेता से जुड़े ड्रग्स स्कैंडल के बाद हो रही है।"]'::jsonb, 'Entertainment', 'World', 1, 1, 0, 0, 0, 2, 'left', 50, NULL, NULL, '{"left": {"count": 1, "sources": ["The Telegraph (India)"], "owners": ["ABP Group"]}, "center": {"count": 1, "sources": ["Outlook India"], "owners": ["Outlook India"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "Outlook India", "owner": "Outlook India", "lean": "center", "language": "en", "url": "https://www.outlookindia.com/art-entertainment/k-drama/yoo-ah-in-returns-to-acting-with-occult-thriller-vampir-after-drug-scandal", "headline": "Yoo Ah - in Comeback : Actor Joins Exhuma Director Vampir Film"}, {"source": "The Telegraph (India)", "owner": "ABP Group", "lean": "left", "language": "en", "url": "https://news.google.?oc=5", "headline": "Yoo Ah-in set to make acting comeback after drug scandal with ‘Exhuma’ helmer’s next film"}]'::jsonb, '{"title": "Actor Yoo Ah-in to Return to Acting After Drug Scandal", "summary": "South Korean actor Yoo Ah-in is reportedly set to make a comeback to acting. He will star in a new film directed by the helmer of ''Exhuma''. This marks his return after a drug scandal. The film is described as a ''Vampire film''.", "summary_points": ["Actor Yoo Ah-in is slated for an acting comeback.", "He will feature in a new film.", "The film will be directed by the director of ''Exhuma''.", "The project is described as a ''Vampire film''.", "This comeback follows a drug scandal involving the actor."], "title_hi": "अभिनेता यू आह-इन ड्रग्स स्कैंडल के बाद अभिनय में वापसी करेंगे", "summary_hi": "दक्षिण कोरियाई अभिनेता यू आह-इन के अभिनय में वापसी करने की खबर है। वह ''एक्सुमा'' के निर्देशक की अगली फिल्म में नजर आएंगे। यह ड्रग्स स्कैंडल के बाद उनकी वापसी का प्रतीक है। फिल्म को ''वैम्पायर फिल्म'' के रूप में वर्णित किया गया है।", "summary_points_hi": ["अभिनेता यू आह-इन अभिनय में वापसी के लिए तैयार हैं।", "वह एक नई फिल्म में नजर आएंगे।", "फिल्म का निर्देशन ''एक्सुमा'' के निर्देशक करेंगे।", "इस परियोजना को ''वैम्पायर फिल्म'' के रूप में वर्णित किया गया है।", "यह वापसी अभिनेता से जुड़े ड्रग्स स्कैंडल के बाद हो रही है।"], "framing": {}, "framing_hi": {}, "topic": "Entertainment", "region": "World", "published_at": null, "image_url": "https://cf-images.assettype.com/outlookindia/2026-08-18/o3gjeqp4/Screenshot-1948-05-27-at-13.25.06.png?&ar=40%3A21&auto=format%2Ccompress&ogImage=true&mode=crop&enlarge=true&overlay=false&overlay_position=bottom&overlay_width=100", "sources": [{"source": "Outlook India", "owner": "Outlook India", "lean": "center", "language": "en", "url": "https://www.outlookindia.com/art-entertainment/k-drama/yoo-ah-in-returns-to-acting-with-occult-thriller-vampir-after-drug-scandal", "headline": "Yoo Ah - in Comeback : Actor Joins Exhuma Director Vampir Film"}, {"source": "The Telegraph (India)", "owner": "ABP Group", "lean": "left", "language": "en", "url": "https://news.google.?oc=5", "headline": "Yoo Ah-in set to make acting comeback after drug scandal with ‘Exhuma’ helmer’s next film"}], "coverage": {"left": {"count": 1, "sources": ["The Telegraph (India)"], "owners": ["ABP Group"]}, "center": {"count": 1, "sources": ["Outlook India"], "owners": ["Outlook India"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://cf-images.assettype.com/outlookindia/2026-08-18/o3gjeqp4/Screenshot-1948-05-27-at-13.25.06.png?&ar=40%3A21&auto=format%2Ccompress&ogImage=true&mode=crop&enlarge=true&overlay=false&overlay_position=bottom&overlay_width=100', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.590606'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15934, 'CBI files chargesheet in Twisha Sharma death case', 'ट्विशा शर्मा मौत मामले में सीबीआई ने दायर की चार्जशीट', 'The Central Bureau of Investigation (CBI) has filed a 636-page chargesheet in the Twisha Sharma death case. The chargesheet was submitted to a Bhopal court. The case involves former judge Giribala Singh and her son, who have been named in the chargesheet. The CBI''s filing suggests the case may involve a suicide, according to one report.', 'केंद्रीय जांच ब्यूरो (सीबीआई) ने ट्विशा शर्मा मौत मामले में 636 पन्नों की चार्जशीट दायर की है। चार्जशीट भोपाल की एक अदालत में पेश की गई। इस मामले में पूर्व न्यायाधीश गिरीबाला सिंह और उनके बेटे का नाम चार्जशीट में शामिल है। एक रिपोर्ट के अनुसार, सीबीआई की चार्जशीट से पता चलता है कि यह मामला आत्महत्या का हो सकता है।', '["CBI filed a 636-page chargesheet in the Twisha Sharma death case.", "The chargesheet was submitted to a Bhopal court.", "Former judge Giribala Singh and her son are named in the chargesheet.", "One report indicates the CBI''s filing suggests the case may involve a suicide."]'::jsonb, '["सीबीआई ने ट्विशा शर्मा मौत मामले में 636 पन्नों की चार्जशीट दायर की है।", "चार्जशीट भोपाल की एक अदालत में पेश की गई।", "पूर्व न्यायाधीश गिरीबाला सिंह और उनके बेटे का नाम चार्जशीट में शामिल है।", "एक रिपोर्ट के अनुसार, सीबीआई की चार्जशीट से पता चलता है कि यह मामला आत्महत्या का हो सकता है।"]'::jsonb, 'Crime & Law', 'India', 0, 1, 1, 0, 0, 2, 'center', 50, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Amar Ujala"], "owners": ["Amar Ujala"]}, "right": {"count": 1, "sources": ["The Pioneer"], "owners": ["The Pioneer"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "Amar Ujala", "owner": "Amar Ujala", "lean": "center", "language": "hi", "url": "https://www.amarujala.com/video/india-news/twisha-sharma-case-cbi-files-636-pages-chargesheet-2026-08-18", "headline": "Twisha Sharma Case: ट्विशा शर्मा ने की थी खुदकुशी? CBI की चार्जशीट में चौंकाने वाला खुलासा"}, {"source": "The Pioneer", "owner": "The Pioneer", "lean": "right", "language": "en", "url": "https://news.google.?oc=5", "headline": "CBI files 636-page chargesheet against ex-judge Giribala Singh and son in Twisha Sharma death case"}]'::jsonb, '{"title": "CBI files chargesheet in Twisha Sharma death case", "summary": "The Central Bureau of Investigation (CBI) has filed a 636-page chargesheet in the Twisha Sharma death case. The chargesheet was submitted to a Bhopal court. The case involves former judge Giribala Singh and her son, who have been named in the chargesheet. The CBI''s filing suggests the case may involve a suicide, according to one report.", "summary_points": ["CBI filed a 636-page chargesheet in the Twisha Sharma death case.", "The chargesheet was submitted to a Bhopal court.", "Former judge Giribala Singh and her son are named in the chargesheet.", "One report indicates the CBI''s filing suggests the case may involve a suicide."], "title_hi": "ट्विशा शर्मा मौत मामले में सीबीआई ने दायर की चार्जशीट", "summary_hi": "केंद्रीय जांच ब्यूरो (सीबीआई) ने ट्विशा शर्मा मौत मामले में 636 पन्नों की चार्जशीट दायर की है। चार्जशीट भोपाल की एक अदालत में पेश की गई। इस मामले में पूर्व न्यायाधीश गिरीबाला सिंह और उनके बेटे का नाम चार्जशीट में शामिल है। एक रिपोर्ट के अनुसार, सीबीआई की चार्जशीट से पता चलता है कि यह मामला आत्महत्या का हो सकता है।", "summary_points_hi": ["सीबीआई ने ट्विशा शर्मा मौत मामले में 636 पन्नों की चार्जशीट दायर की है।", "चार्जशीट भोपाल की एक अदालत में पेश की गई।", "पूर्व न्यायाधीश गिरीबाला सिंह और उनके बेटे का नाम चार्जशीट में शामिल है।", "एक रिपोर्ट के अनुसार, सीबीआई की चार्जशीट से पता चलता है कि यह मामला आत्महत्या का हो सकता है।"], "framing": {}, "framing_hi": {}, "topic": "Crime & Law", "region": "India", "published_at": null, "image_url": "", "sources": [{"source": "Amar Ujala", "owner": "Amar Ujala", "lean": "center", "language": "hi", "url": "https://www.amarujala.com/video/india-news/twisha-sharma-case-cbi-files-636-pages-chargesheet-2026-08-18", "headline": "Twisha Sharma Case: ट्विशा शर्मा ने की थी खुदकुशी? CBI की चार्जशीट में चौंकाने वाला खुलासा"}, {"source": "The Pioneer", "owner": "The Pioneer", "lean": "right", "language": "en", "url": "https://news.google.?oc=5", "headline": "CBI files 636-page chargesheet against ex-judge Giribala Singh and son in Twisha Sharma death case"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Amar Ujala"], "owners": ["Amar Ujala"]}, "right": {"count": 1, "sources": ["The Pioneer"], "owners": ["The Pioneer"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, NULL, FALSE, FALSE, 'llm', 'sl-15341', NULL, '2026-08-18T10:30:17.566413'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15933, 'Uber Eats and Zipline Partner for Drone Food Delivery in US', 'उबर ईट्स और ज़िपलाइन ने अमेरिका में ड्रोन फूड डिलीवरी के लिए साझेदारी की', 'Uber Eats and Zipline have partnered to offer food delivery via drones in the United States. The collaboration aims to deliver meals within 10 minutes. This deal is expected to significantly alter the landscape of food delivery services.', 'उबर ईट्स और ज़िपलाइन ने संयुक्त राज्य अमेरिका में ड्रोन के माध्यम से भोजन की डिलीवरी की पेशकश करने के लिए साझेदारी की है। इस सहयोग का उद्देश्य 10 मिनट के भीतर भोजन पहुंचाना है। इस सौदे से खाद्य वितरण सेवाओं के परिदृश्य में महत्वपूर्ण बदलाव आने की उम्मीद है।', '["Uber Eats and Zipline are collaborating on drone delivery.", "The service will deliver food via drones.", "Deliveries are expected to take approximately 10 minutes.", "The partnership is anticipated to transform the food delivery industry."]'::jsonb, '["उबर ईट्स और ज़िपलाइन ड्रोन डिलीवरी पर सहयोग कर रहे हैं।", "यह सेवा ड्रोन के माध्यम से भोजन वितरित करेगी।", "डिलीवरी में लगभग 10 मिनट लगने की उम्मीद है।", "इस साझेदारी से खाद्य वितरण उद्योग में क्रांति आने की उम्मीद है।"]'::jsonb, 'Economy', 'World', 0, 2, 0, 0, 0, 2, 'center', 100, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Patrika", "Reuters"], "owners": ["Patrika", "Reuters"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "Reuters", "owner": "Reuters", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMitAFBVV95cUxQVGIxTkgzWjVwcGR3eUpmWi1fbjQ5TXo1ZWZzOVExUGJxdTJ5XzVZOXVTRmNXeFRLTXplV0JFcFFhUEhrblNPaTcwMGpxZ0hNWHR0OHp4dERKVUVnVFh3c1BNU3R4bFozMkVtUlBScmJkNVlxXzg1QWpWb1BCZEVVbktZOS0yZHRJeU5MUUhQS1Q3RE1jS3lOa3RrcUJlN3BVbVpsZnB0LW5iLTlNcUlyWHRHdDc?oc=5", "headline": "Uber, Zipline partner on US drone delivery for Uber Eats"}, {"source": "Patrika", "owner": "Patrika", "lean": "center", "language": "hi", "url": "https://news.google.?oc=5", "headline": "10 मिनट में ड्रोन से आएगा खाना, Uber Eats और Zipline की डील से बदल सकती है फूड डिलीवरी की तस्वीर"}]'::jsonb, '{"title": "Uber Eats and Zipline Partner for Drone Food Delivery in US", "summary": "Uber Eats and Zipline have partnered to offer food delivery via drones in the United States. The collaboration aims to deliver meals within 10 minutes. This deal is expected to significantly alter the landscape of food delivery services.", "summary_points": ["Uber Eats and Zipline are collaborating on drone delivery.", "The service will deliver food via drones.", "Deliveries are expected to take approximately 10 minutes.", "The partnership is anticipated to transform the food delivery industry."], "title_hi": "उबर ईट्स और ज़िपलाइन ने अमेरिका में ड्रोन फूड डिलीवरी के लिए साझेदारी की", "summary_hi": "उबर ईट्स और ज़िपलाइन ने संयुक्त राज्य अमेरिका में ड्रोन के माध्यम से भोजन की डिलीवरी की पेशकश करने के लिए साझेदारी की है। इस सहयोग का उद्देश्य 10 मिनट के भीतर भोजन पहुंचाना है। इस सौदे से खाद्य वितरण सेवाओं के परिदृश्य में महत्वपूर्ण बदलाव आने की उम्मीद है।", "summary_points_hi": ["उबर ईट्स और ज़िपलाइन ड्रोन डिलीवरी पर सहयोग कर रहे हैं।", "यह सेवा ड्रोन के माध्यम से भोजन वितरित करेगी।", "डिलीवरी में लगभग 10 मिनट लगने की उम्मीद है।", "इस साझेदारी से खाद्य वितरण उद्योग में क्रांति आने की उम्मीद है।"], "framing": {}, "framing_hi": {}, "topic": "Economy", "region": "World", "published_at": null, "image_url": "", "sources": [{"source": "Reuters", "owner": "Reuters", "lean": "center", "language": "en", "url": "https://news.google.com/rss/articles/CBMitAFBVV95cUxQVGIxTkgzWjVwcGR3eUpmWi1fbjQ5TXo1ZWZzOVExUGJxdTJ5XzVZOXVTRmNXeFRLTXplV0JFcFFhUEhrblNPaTcwMGpxZ0hNWHR0OHp4dERKVUVnVFh3c1BNU3R4bFozMkVtUlBScmJkNVlxXzg1QWpWb1BCZEVVbktZOS0yZHRJeU5MUUhQS1Q3RE1jS3lOa3RrcUJlN3BVbVpsZnB0LW5iLTlNcUlyWHRHdDc?oc=5", "headline": "Uber, Zipline partner on US drone delivery for Uber Eats"}, {"source": "Patrika", "owner": "Patrika", "lean": "center", "language": "hi", "url": "https://news.google.?oc=5", "headline": "10 मिनट में ड्रोन से आएगा खाना, Uber Eats और Zipline की डील से बदल सकती है फूड डिलीवरी की तस्वीर"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 2, "sources": ["Patrika", "Reuters"], "owners": ["Patrika", "Reuters"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, NULL, FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.543203'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degrad