INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15930, 'AIIMS Board Rules Twisha Sharma''s Death a Suicide', 'एम्स बोर्ड ने कहा, त्विशा शर्मा की मौत आत्महत्या से हुई', 'An AIIMS medical board has concluded that Twisha Sharma died by suicide. The board''s findings, reported by multiple outlets, state there were no signs of assault. The conclusion was reached after an examination by the medical board.', 'एम्स के एक मेडिकल बोर्ड ने यह निष्कर्ष निकाला है कि त्विशा शर्मा की मौत आत्महत्या से हुई। कई आउटलेट्स द्वारा रिपोर्ट किए गए बोर्ड के निष्कर्षों में कहा गया है कि हमले के कोई संकेत नहीं थे। यह निष्कर्ष मेडिकल बोर्ड द्वारा की गई जांच के बाद निकाला गया।', '["AIIMS medical board determined Twisha Sharma''s death was by suicide.", "The board found no evidence of assault.", "The conclusion was based on an examination by the medical board."]'::jsonb, '["एम्स मेडिकल बोर्ड ने निर्धारित किया कि त्विशा शर्मा की मौत आत्महत्या से हुई।", "बोर्ड को हमले का कोई सबूत नहीं मिला।", "यह निष्कर्ष मेडिकल बोर्ड द्वारा की गई जांच पर आधारित था।"]'::jsonb, 'Crime & Law', 'India', 1, 1, 0, 0, 0, 2, 'left', 50, NULL, NULL, '{"left": {"count": 1, "sources": ["National Herald"], "owners": ["National Herald"]}, "center": {"count": 1, "sources": ["The Tribune"], "owners": ["The Tribune"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "National Herald", "owner": "National Herald", "lean": "left", "language": "en", "url": "https://news.google.?oc=5", "headline": "AIIMS medical board concludes Twisha Sharma died by suicide"}, {"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Twisha Sharma died by suicidal hanging, AIIMS board finds; no signs of assault"}]'::jsonb, '{"title": "AIIMS Board Rules Twisha Sharma''s Death a Suicide", "summary": "An AIIMS medical board has concluded that Twisha Sharma died by suicide. The board''s findings, reported by multiple outlets, state there were no signs of assault. The conclusion was reached after an examination by the medical board.", "summary_points": ["AIIMS medical board determined Twisha Sharma''s death was by suicide.", "The board found no evidence of assault.", "The conclusion was based on an examination by the medical board."], "title_hi": "एम्स बोर्ड ने कहा, त्विशा शर्मा की मौत आत्महत्या से हुई", "summary_hi": "एम्स के एक मेडिकल बोर्ड ने यह निष्कर्ष निकाला है कि त्विशा शर्मा की मौत आत्महत्या से हुई। कई आउटलेट्स द्वारा रिपोर्ट किए गए बोर्ड के निष्कर्षों में कहा गया है कि हमले के कोई संकेत नहीं थे। यह निष्कर्ष मेडिकल बोर्ड द्वारा की गई जांच के बाद निकाला गया।", "summary_points_hi": ["एम्स मेडिकल बोर्ड ने निर्धारित किया कि त्विशा शर्मा की मौत आत्महत्या से हुई।", "बोर्ड को हमले का कोई सबूत नहीं मिला।", "यह निष्कर्ष मेडिकल बोर्ड द्वारा की गई जांच पर आधारित था।"], "framing": {}, "framing_hi": {}, "topic": "Crime & Law", "region": "India", "published_at": null, "image_url": "", "sources": [{"source": "National Herald", "owner": "National Herald", "lean": "left", "language": "en", "url": "https://news.google.?oc=5", "headline": "AIIMS medical board concludes Twisha Sharma died by suicide"}, {"source": "The Tribune", "owner": "The Tribune", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Twisha Sharma died by suicidal hanging, AIIMS board finds; no signs of assault"}], "coverage": {"left": {"count": 1, "sources": ["National Herald"], "owners": ["National Herald"]}, "center": {"count": 1, "sources": ["The Tribune"], "owners": ["The Tribune"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, NULL, FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.476185'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15929, 'Tamil Nadu Minister Vows to Block Harmful Hydrocarbon Projects', 'तमिलनाडु के मंत्री ने हानिकारक हाइड्रोकार्बन परियोजनाओं को रोकने की कसम खाई', 'Tamil Nadu Minister for Environment, Climate Change, and Forests, Thiru. Siva V. Meyyanathan, stated that the state government will not permit any hydrocarbon projects that negatively impact the public. He made this statement in response to concerns raised about the proposed ONGC gas exploration project in the Cauvery delta region. The minister assured that the government is committed to protecting the interests of the people and the environment.', 'पर्यावरण, जलवायु परिवर्तन और वन मंत्री, थिरु. शिव वी. मेयनाथन ने कहा कि राज्य सरकार किसी भी हाइड्रोकार्बन परियोजना की अनुमति नहीं देगी जो जनता पर नकारात्मक प्रभाव डालती हो। उन्होंने कावेरी डेल्टा क्षेत्र में प्रस्तावित ओएनजीसी गैस अन्वेषण परियोजना के बारे में उठाई गई चिंताओं के जवाब में यह बयान दिया। मंत्री ने आश्वासन दिया कि सरकार लोगों के हितों और पर्यावरण की रक्षा के लिए प्रतिबद्ध है।', '["Tamil Nadu Minister Thiru. Siva V. Meyyanathan stated the government will not allow projects negatively impacting people.", "The statement was made in the context of a proposed ONGC gas exploration project in the Cauvery delta region.", "The minister assured protection for public interests and the environment.", "The government''s stance is to prevent harmful projects."]'::jsonb, '["तमिलनाडु के मंत्री थिरु. शिव वी. मेयनाथन ने कहा कि सरकार ऐसे प्रोजेक्ट्स की अनुमति नहीं देगी जो लोगों पर नकारात्मक प्रभाव डालते हों।", "यह बयान कावेरी डेल्टा क्षेत्र में प्रस्तावित ओएनजीसी गैस अन्वेषण परियोजना के संबंध में उठाई गई चिंताओं के जवाब में दिया गया था।", "मंत्री ने जनता के हितों और पर्यावरण की सुरक्षा का आश्वासन दिया।", "सरकार का रुख हानिकारक परियोजनाओं को रोकना है।"]'::jsonb, 'Environment', 'India', 0, 1, 1, 0, 0, 2, 'center', 50, NULL, NULL, '{"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Deccan Chronicle"], "owners": ["Deccan Chronicle"]}, "right": {"count": 1, "sources": ["The Pioneer"], "owners": ["The Pioneer"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "The Pioneer", "owner": "The Pioneer", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMikgFBVV95cUxOb050NUMtYnhLbkhhUHp5YlFyTHBaemREaTF3dkkzQ05ZRU9mdHFxaDZIeVFIMXhTU1U2UXhjUk96Skx5Rk1RWDhoTVVscnRiX3RON3c4STZJazRfR2JJV00ydHE3enF1dDNOOXFmOTBLVlYyNThLNHdTM2JLaW5WR1UxN0xqVDhaQjJRZHRFNTBVQQ?oc=5", "headline": "Hydrocarbon project: TN govt wont allow projects negatively..."}, {"source": "Deccan Chronicle", "owner": "Deccan Chronicle", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Won’t Allow Projects Negatively Impacting People, TN Minister on Hydrocarbon Project"}]'::jsonb, '{"title": "Tamil Nadu Minister Vows to Block Harmful Hydrocarbon Projects", "summary": "Tamil Nadu Minister for Environment, Climate Change, and Forests, Thiru. Siva V. Meyyanathan, stated that the state government will not permit any hydrocarbon projects that negatively impact the public. He made this statement in response to concerns raised about the proposed ONGC gas exploration project in the Cauvery delta region. The minister assured that the government is committed to protecting the interests of the people and the environment.", "summary_points": ["Tamil Nadu Minister Thiru. Siva V. Meyyanathan stated the government will not allow projects negatively impacting people.", "The statement was made in the context of a proposed ONGC gas exploration project in the Cauvery delta region.", "The minister assured protection for public interests and the environment.", "The government''s stance is to prevent harmful projects."], "title_hi": "तमिलनाडु के मंत्री ने हानिकारक हाइड्रोकार्बन परियोजनाओं को रोकने की कसम खाई", "summary_hi": "पर्यावरण, जलवायु परिवर्तन और वन मंत्री, थिरु. शिव वी. मेयनाथन ने कहा कि राज्य सरकार किसी भी हाइड्रोकार्बन परियोजना की अनुमति नहीं देगी जो जनता पर नकारात्मक प्रभाव डालती हो। उन्होंने कावेरी डेल्टा क्षेत्र में प्रस्तावित ओएनजीसी गैस अन्वेषण परियोजना के बारे में उठाई गई चिंताओं के जवाब में यह बयान दिया। मंत्री ने आश्वासन दिया कि सरकार लोगों के हितों और पर्यावरण की रक्षा के लिए प्रतिबद्ध है।", "summary_points_hi": ["तमिलनाडु के मंत्री थिरु. शिव वी. मेयनाथन ने कहा कि सरकार ऐसे प्रोजेक्ट्स की अनुमति नहीं देगी जो लोगों पर नकारात्मक प्रभाव डालते हों।", "यह बयान कावेरी डेल्टा क्षेत्र में प्रस्तावित ओएनजीसी गैस अन्वेषण परियोजना के संबंध में उठाई गई चिंताओं के जवाब में दिया गया था।", "मंत्री ने जनता के हितों और पर्यावरण की सुरक्षा का आश्वासन दिया।", "सरकार का रुख हानिकारक परियोजनाओं को रोकना है।"], "framing": {}, "framing_hi": {}, "topic": "Environment", "region": "India", "published_at": null, "image_url": "", "sources": [{"source": "The Pioneer", "owner": "The Pioneer", "lean": "right", "language": "en", "url": "https://news.google.com/rss/articles/CBMikgFBVV95cUxOb050NUMtYnhLbkhhUHp5YlFyTHBaemREaTF3dkkzQ05ZRU9mdHFxaDZIeVFIMXhTU1U2UXhjUk96Skx5Rk1RWDhoTVVscnRiX3RON3c4STZJazRfR2JJV00ydHE3enF1dDNOOXFmOTBLVlYyNThLNHdTM2JLaW5WR1UxN0xqVDhaQjJRZHRFNTBVQQ?oc=5", "headline": "Hydrocarbon project: TN govt wont allow projects negatively..."}, {"source": "Deccan Chronicle", "owner": "Deccan Chronicle", "lean": "center", "language": "en", "url": "https://news.google.?oc=5", "headline": "Won’t Allow Projects Negatively Impacting People, TN Minister on Hydrocarbon Project"}], "coverage": {"left": {"count": 0, "sources": [], "owners": []}, "center": {"count": 1, "sources": ["Deccan Chronicle"], "owners": ["Deccan Chronicle"]}, "right": {"count": 1, "sources": ["The Pioneer"], "owners": ["The Pioneer"]}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, NULL, FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.452569'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
